// Big Bear Lake survey data, baked by tools/bigbear (see docs/big-bear-research.md).
// Depth grid: BBMWD 2008 multibeam hydrographic survey (colour-ramp read off the chart and fitted onto the OpenStreetMap shoreline);
// land DEM: SRTM 30 m sampled every 200 m. Game metres = real metres x 0.4.
const dec = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
export const BBG = { nx: 521, nz: 185, x0: -2082.72, z0: -738.31, cell: 8.0, q: dec(''), sd: new Int8Array(dec('').buffer) };   // q: depth in 0.1 m (land nodes copy the nearest water); sd: signed distance to the shoreline in game metres, + on land
export const BBD = { n: 61, step: 80.0, e: new Int16Array(dec('').buffer) };   // metres above the lake surface (2057.5 m), 61 x 61 posts
